        const bal = u ? parseFloat(u.walletBalance || u.marginBalance || 0) : parseFloat(acc.totalWalletBalance || 0);
        set(`Verbonden. Futures-saldo: ${bal.toFixed(2)} USDT. Klaar voor margin-modus.`);
        try { marginLoadPrec(); } catch (e) {}
