        const bal = u ? parseFloat(u.availableBalance || u.walletBalance || 0) : parseFloat(acc.availableBalance || acc.totalWalletBalance || 0);
        if (!(bal > 0)) { set('Geen vrij USDT-saldo op de futures-testnet.', true); return; }
